import test from "node:test";
import assert from "node:assert/strict";
import { mkdirSync, readFileSync, rmSync, writeFileSync, existsSync } from "node:fs";
import { startServer } from "./lib/server.mjs";
import { launch } from "./lib/cdp.mjs";

const ROOT = "/tmp/voicebox-mini-app-sync";
const SHELF_HOST = "/tmp/voicebox-mini-app-sync-ext"; // ISOLATED host dir so the shelf is observable
let server;
test.before(async () => {
  rmSync(ROOT, { recursive: true, force: true });
  rmSync(SHELF_HOST, { recursive: true, force: true });
  mkdirSync(`${ROOT}/proposals`, { recursive: true });
  writeFileSync(`${ROOT}/proposals/draft.html`, "<h1>before</h1>");
  server = await startServer({ env: { VOICEBOX_INSTANCE: "mini-app-sync", VOICEBOX_EXTENSIONS_DIR: SHELF_HOST } });
});
test.after(async () => { await server?.stop?.(); });

test("saving an HTML file inside a folder syncs the mini-app by its LEAF name (voicebox-beads-m4no)", { timeout: 180000 }, async () => {
  await fetch(`${server.base}/api/root`, { method: "POST", headers: { "content-type": "application/json", "x-voicebox-host-token": server.hostToken }, body: JSON.stringify({ project: "sync", root: { kind: "machine", path: ROOT } }) }).then((r) => r.json());
  const page = await launch({ width: 1280, height: 900 });
  try {
    await page.goto(`${server.base}/`);
    await page.waitFor(() => document.querySelector("#files .file-open"), { label: "the file list" });
    // Collect console.warn BEFORE any save, so a swallowed-turned-named refusal cannot hide:
    await page.evaluate(() => { window.__syncWarnings = []; const ow = console.warn.bind(console); console.warn = (...a) => { window.__syncWarnings.push(a.join(" ")); ow(...a); }; });
    await page.evaluate(() => document.getElementById("sqeh-files-bubble")?.click());
    await page.click('#files .file-open[data-file="proposals"]');
    await page.waitFor(() => document.querySelector('#files .file-open[data-file="draft.html"]'), { label: "inside the folder" });
    await page.click('#files .file-open[data-file="draft.html"]');
    await page.waitFor(() => document.getElementById("file-edit") && !document.getElementById("file-edit").disabled, { label: "the reader with Edit enabled" });
    await page.evaluate(() => document.getElementById("file-edit").click());
    await page.waitFor(() => !document.getElementById("file-save").hidden, { label: "edit mode" });
    await page.evaluate(() => { const ed = document.getElementById("file-editor"); ed.value = "<h1>after</h1>"; ed.dispatchEvent(new Event("input", { bubbles: true })); });
    await page.evaluate(() => document.getElementById("file-save").click());
    await page.waitFor(() => document.getElementById("reader-facts")?.textContent?.includes("saved"), { label: "the save reported" });

    // THE FIX, end to end: the sync asked for the LEAF name and it landed.
    const apps = await fetch(`${server.base}/api/mini-apps`).then((r) => r.json());
    const synced = (apps.miniApps ?? []).find((a) => (a.fileName ?? "").endsWith("draft.html"));
    assert.ok(synced, `the mini-app sync landed (got ${JSON.stringify(apps.miniApps?.map((a) => a.fileName))})`);
    assert.equal(synced.fileName, "draft.html", "by its LEAF name — the joined path never reached the API");
    assert.ok(existsSync(`${SHELF_HOST}/mini-apps/draft.html`), "the shelf copy is on disk under the leaf name");
    assert.equal(readFileSync(`${ROOT}/proposals/draft.html`, "utf8"), "<h1>after</h1>", "and the real file save itself landed");
    const warnings = await page.evaluate(() => window.__syncWarnings);
    assert.deepEqual(warnings.filter((w) => w.includes("[mini-app-sync]")), [], "no sync warning on the happy path");
  } finally {
    await page.close();
  }
});

